mapper.select:
select i.id, i.task_id, i.asset_id, a.asset_code, a.name as asset_name, i.system_user_id, u1.real_name as system_user_name, i.result, i.actual_user_id, u2.real_name as actual_user_name from inventory_detail i left join asset a on i.asset_id = a.id and a.is_deleted = 0 left join user u1 on i.system_user_id = u1.id and u1.is_deleted = 0 left join user u2 on i.actual_user_id = u2.id and u2.is_deleted = 0
i.task_id = #{taskId}
AND i.result = #{result}
